// Payment subscore per account: 100 - 25 per failed payment - 10 per open invoice.
var mapping = $('Load Account Mapping').all().map(function(i){ return i.json; });
var invoices = $('Fetch Recent Invoices').all().map(function(i){ return i.json; });
var byStripe = {};
for (var m = 0; m < mapping.length; m++) {
  if (mapping[m].stripe_customer_id) byStripe[String(mapping[m].stripe_customer_id)] = mapping[m];
}
var failed = {}, openInv = {};
for (var k = 0; k < invoices.length; k++) {
  var inv = invoices[k];
  var cid = String(inv.customer || '');
  if (!cid || !byStripe[cid]) continue;
  if (inv.status === 'open' && Number(inv.attempt_count || 0) > 0) failed[cid] = (failed[cid] || 0) + 1;
  else if (inv.status === 'open' || inv.status === 'draft') openInv[cid] = (openInv[cid] || 0) + 1;
}
var out = [];
for (var s = 0; s < $input.all().length; s++) {
  var sub = $input.all()[s].json;
  var cid2 = String(sub.customer || '');
  var mp = byStripe[cid2];
  if (!mp) continue;
  var f = failed[cid2] || 0, o = openInv[cid2] || 0;
  var score = 100 - f * 25 - o * 10;
  if (score < 0) score = 0;
  var risks = [];
  if (f > 0) risks.push(f + ' failed payments');
  if (o > 0) risks.push(o + ' open invoices');
  out.push({ json: { account_key: mp.account_key, account_name: mp.account_name,
    payment_subscore: score, payment_risks: risks, failed_payments: f, open_invoices: o } });
}
return out;

// Support subscore per org. Classifications join to tickets by index (1:1 order).
var mapping = $('Load Account Mapping').all().map(function(i){ return i.json; });
var tickets = $('Fetch Recent Tickets').all().map(function(i){ return i.json; });
var classes = $('Classify Ticket Sentiment').all().map(function(i){ return i.json; });
var byOrg = {};
for (var m = 0; m < mapping.length; m++) {
  if (mapping[m].zendesk_org_id) byOrg[String(mapping[m].zendesk_org_id)] = mapping[m];
}
var stats = {};
for (var t = 0; t < tickets.length; t++) {
  var oid = String(tickets[t].organization_id || '');
  if (!oid || !byOrg[oid]) continue;
  var c = classes[t] || {};
  var msg = c.message && c.message.content ? c.message.content : '{}';
  var p; try { p = JSON.parse(String(msg).replace(/\u0060\u0060\u0060/g, '')); } catch (e) { p = {}; }
  var st = stats[oid] || { n: 0, angry: 0, bugs: 0 };
  st.n++;
  if (p.sentiment === 'angry' || p.sentiment === 'negative') st.angry++;
  if (p.is_bug === true && tickets[t].status !== 'closed' && tickets[t].status !== 'solved') st.bugs++;
  stats[oid] = st;
}
var out = [];
for (var oid2 in stats) {
  var s2 = stats[oid2], mp2 = byOrg[oid2];
  var angryRate = s2.n > 0 ? s2.angry / s2.n : 0;
  var score = 100 - Math.round(angryRate * 60) - s2.bugs * 10 - Math.min(20, Math.max(0, (s2.n - 5) * 2));
  if (score < 0) score = 0;
  var risks = [];
  if (angryRate >= 0.3) risks.push(Math.round(angryRate * 100) + '% negative tickets');
  if (s2.bugs > 0) risks.push(s2.bugs + ' open bugs');
  if (s2.n >= 10) risks.push('high ticket volume (' + s2.n + ')');
  out.push({ json: { account_key: mp2.account_key, account_name: mp2.account_name,
    support_subscore: score, support_risks: risks, ticket_count: s2.n } });
}
return out;

// Usage subscore per account from product metrics.
var cfg = $('Workflow Configuration').first().json;
var lookback = Number(cfg.lookbackDays) || 30;
var mapping = $('Load Account Mapping').all().map(function(i){ return i.json; });
var byProd = {};
for (var m = 0; m < mapping.length; m++) {
  if (mapping[m].product_account_id) byProd[String(mapping[m].product_account_id)] = mapping[m];
}
var out = [];
for (var k = 0; k < $input.all().length; k++) {
  var u = $input.all()[k].json;
  var aid = String(u.account_id || u.id || '');
  var mp = byProd[aid];
  if (!mp) continue;
  var activeDays = Number(u.active_days || u.activeDays || 0);
  var featUses = Number(u.key_feature_uses || u.keyFeatureUses || 0);
  var score = Math.round(Math.min(1, activeDays / lookback) * 80 + Math.min(20, featUses));
  var risks = [];
  if (activeDays < lookback * 0.3) risks.push('low activity (' + activeDays + ' active days)');
  if (featUses === 0) risks.push('key features unused');
  out.push({ json: { account_key: mp.account_key, account_name: mp.account_name,
    usage_subscore: score, usage_risks: risks, active_days: activeDays } });
}
return out;

// Left-join arm subscores per account_key.
var mapping = $('Load Account Mapping').all().map(function(i){ return i.json; });
var arms = $input.all().map(function(i){ return i.json; });
var byKey = {};
for (var a = 0; a < arms.length; a++) {
  var r = arms[a], k = r.account_key;
  var e = byKey[k] || { account_key: k };
  for (var f in r) { if (f !== 'account_key' && f !== 'account_name') e[f] = r[f]; }
  if (r.account_name) e.account_name = r.account_name;
  byKey[k] = e;
}
var out = [];
for (var m2 = 0; m2 < mapping.length; m2++) {
  var mp = mapping[m2], e2 = byKey[mp.account_key] || { account_key: mp.account_key };
  e2.account_name = mp.account_name;
  e2.hubspot_company_id = mp.hubspot_company_id || '';
  e2.csm_owner = mp.csm_owner || '';
  e2.csm_email = mp.csm_email || '';
  var gaps = [];
  if (e2.payment_subscore === undefined) gaps.push('payment');
  if (e2.support_subscore === undefined) gaps.push('support');
  if (e2.usage_subscore === undefined) gaps.push('usage');
  e2.data_gaps = gaps;
  out.push({ json: e2 });
}
return out;

// Weighted 0-100 score over available arms, with named risk drivers.
var cfg = $('Workflow Configuration').first().json;
var wP = Number(cfg.weightPayment) || 35, wS = Number(cfg.weightSupport) || 35, wU = Number(cfg.weightUsage) || 30;
var out = [];
for (var k = 0; k < $input.all().length; k++) {
  var j = $input.all()[k].json;
  var parts = [];
  if (j.payment_subscore !== undefined) parts.push({ w: wP, s: j.payment_subscore, name: 'payment', risks: j.payment_risks || [] });
  if (j.support_subscore !== undefined) parts.push({ w: wS, s: j.support_subscore, name: 'support', risks: j.support_risks || [] });
  if (j.usage_subscore !== undefined) parts.push({ w: wU, s: j.usage_subscore, name: 'usage', risks: j.usage_risks || [] });
  var score = null, drivers = [];
  if (parts.length > 0) {
    var num = 0, den = 0;
    for (var p = 0; p < parts.length; p++) { num += parts[p].w * parts[p].s; den += parts[p].w; }
    score = Math.round(num / den);
    parts.sort(function(a, b){ return a.s - b.s; });
    for (var d = 0; d < Math.min(2, parts.length); d++) {
      var r0 = parts[d].risks.length > 0 ? parts[d].risks[0] : 'below average';
      drivers.push(parts[d].name + ': ' + r0);
    }
  }
  j.health_score = score;
  j.drivers = drivers;
  j.timestamp = new Date().toISOString().slice(0, 10);
  out.push({ json: j });
}
return out;

// Day-over-day delta vs the latest snapshot per account.
var prior = $('Load Prior Scores').all().map(function(i){ return i.json; });
var latest = {};
for (var p = 0; p < prior.length; p++) {
  var r = prior[p];
  var k = String(r.account_key || '');
  if (!k) continue;
  if (!latest[k] || String(r.date || '') > String(latest[k].date || '')) latest[k] = r;
}
var out = [];
for (var k2 = 0; k2 < $input.all().length; k2++) {
  var j = $input.all()[k2].json;
  var prev = latest[String(j.account_key)];
  j.trend_delta = (prev && j.health_score !== null && prev.score !== undefined)
    ? (Number(j.health_score) - Number(prev.score)) : null;
  out.push({ json: j });
}
return out;

// Aggregate all watchlist accounts into one digest email body.
var lines = [];
for (var k = 0; k < $input.all().length; k++) {
  var j = $input.all()[k].json;
  var delta = j.trend_delta !== null ? ' (' + (j.trend_delta >= 0 ? '+' : '') + j.trend_delta + ' vs yesterday)' : '';
  lines.push('- ' + j.account_name + ': ' + j.health_score + '/100' + delta + ' | ' + j.drivers.join('; '));
}
return [{ json: {
  digest_body: 'Morning watchlist: ' + $input.all().length + ' accounts need attention today.\n\n' + lines.join('\n')
    + '\n\nFull scores are in the HealthLog sheet.',
  watch_count: $input.all().length
} }];
